import React from 'react'
import { StatusBar } from 'expo-status-bar'
import { SafeAreaProvider } from 'react-native-safe-area-context'
import { WdkAppProvider } from '@tetherto/wdk-react-native-core'
// Generated by `wdk-worklet-bundler generate` (postinstall): WDK + the BTC module for the Bare worklet.
import wdkBundle from './.wdk-bundle/wdk-worklet.bundle.js'
import { wdkConfigs } from './src/wallet/config'
import { Gate } from './src/ui/Gate'
